+++ b/tests/anthropic-sdk.test.js
@@ -0,0 +1,31 @@
+const fs = require('fs');
+const path = require('path');
+
+test('SDK 1.x sends anthropic-version 2026-10-21 and no sampling params', async () => {
+  const Anthropic = require('@anthropic-ai/sdk');
+  const pkg = JSON.parse(fs.readFileSync(path.join(__dirname, '../node_modules/@anthropic-ai/sdk/package.json'), 'utf8'));
+  expect(pkg.version.startsWith('1.')).toBe(true);
+  let captured;
+  const fetch = async (url, init) => {
+    captured = { body: JSON.parse(init.body), headers: new Headers(init.headers) };
+    return new Response(JSON.stringify({
+      id: 'm', type: 'message', role: 'assistant', model: 'x',
+      content: [{ type: 'text', text: 'hi' }], stop_reason: 'end_turn',
+      usage: { input_tokens: 1, output_tokens: 1 },
+    }), { headers: { 'content-type': 'application/json' } });
+  };
+  const client = new Anthropic({ apiKey: 'dummy', fetch });
+  const r = await client.messages.create({
+    model: 'claude-sonnet-4-6', max_tokens: 10, system: 's',
+    messages: [{ role: 'user', content: 'q' }],
+  });
+  expect(r.content[0].text).toBe('hi');
+  expect(captured.headers.get('anthropic-version')).toBe('2026-10-21');
+  for (const k of ['temperature', 'top_p', 'top_k']) expect(captured.body).not.toHaveProperty(k);
+});
+
+test('proxy source sends no sampling params', () => {
+  const src = fs.readFileSync(path.join(__dirname, '../scripts/playbook-editor-proxy.js'), 'utf8');
+  const call = src.slice(src.indexOf('client.messages.create('), src.indexOf('client.messages.create(') + 300);
+  expect(call).not.toMatch(/temperature|top_p|top_k/);
+});
